import sqlite3
from app.config import settings

class SQLiteDB():
    def create_conn(self):
        self.conn = sqlite3.connect('AiQA_DB.db')
        
       

    def sqlite_procedure(self,story,testcase_details,embedding):
        self.create_conn()
        self.cursor = self.conn.cursor()
        self.create_tables()
        self.insert_data(story,testcase_details,embedding)
        self.conn.commit()
        self.conn.close()
        #print("Data inserted successfully")

  
    def create_tables(self):
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS story (
                        story_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        title TEXT NOT NULL,
                        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                        model_used TEXT NOT NULL,
                        status TEXT,
                        provider TEXT,
                        embedding TEXT
                    )''')
        #print("Table 'story' created successfully")
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS testcase (
                        testcase_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        story_id INTEGER,
                        title TEXT NOT NULL,
                        preconditions TEXT,
                        test_steps TEXT,
                        expected_result TEXT,
                        priority TEXT,
                        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (story_id) REFERENCES story(story_id)
                    )''')

    def insert_data(self, story,testcase_details,embedding):
        # print("====inside insert data====")
        story_id=self.insert_story(story, self.get_model_used(), self.get_status(testcase_details), self.get_provider(),
                                   embedding)
        for data in testcase_details:
            self.insert_testcase(story_id, data['title'], data['preconditions'], data['test_steps'], data['expected_result'], 
                                 data['priority'])

    def get_status(self,testcase_details):
        status = "Failed"
        if testcase_details:
            status="Success"
        return status

    def get_model_used(self):
        if settings.AI_PROVIDER=="ollama":
            model_used=settings.OLLAMA_MODEL
        elif settings.AI_PROVIDER=="huggingface":
            model_used=settings.HF_MODEL
        elif settings.AI_PROVIDER=="langchain":
            model_used=settings.OLLAMA_MODEL

        return model_used

    def get_provider(self):
        return settings.AI_PROVIDER
    def insert_story(self, story, model_used, success, provider, embedding):
        # print("====inside insert story====")
        self.cursor.execute(''' INSERT INTO story(
        title, model_used, status, provider,embedding)
        VALUES (?,?,?,?,?)
        ''',(story,model_used,success, provider,embedding))

        return self.cursor.lastrowid #

    def insert_testcase(self,story_id, title, preconditions, test_steps, expected_result, priority):
        # print("====inside insert test case====")
        self.cursor.execute(''' INSERT INTO testcase(story_id, title, preconditions, test_steps, expected_result, priority)
                        VALUES(?,?,?,?,?,?)
                        ''',(story_id, title, preconditions, test_steps, expected_result, priority))

    def get_story_table(self):
        self.create_conn()
        self.conn.row_factory = sqlite3.Row  # allows column-name access
        self.cursor = self.conn.cursor()
        self.cursor.execute("SELECT story_id, title, embedding FROM story GROUP BY title;")
        rows = self.cursor.fetchall()
        # Convert sqlite3.Row to dict
        rows_as_dicts = [dict(row) for row in rows]
        self.conn.close()
        return rows_as_dicts

    def get_testcases_table(self,story_list):
        self.create_conn()
        self.conn.row_factory = sqlite3.Row  # allows column-name access
        self.cursor = self.conn.cursor()
        story_ids = [story["story_id"] for story in story_list] 
        placeholders = ",".join(["?"] * len(story_ids))

        query = f"""
            SELECT *
            FROM testcase
            WHERE story_id IN ({placeholders})
        """

        self.cursor.execute(query, story_ids)
        rows_as_dicts = [dict(row) for row in self.cursor.fetchall()]    
        self.conn.close()
        return rows_as_dicts

